// React 18: useTransition 保持输入响应
import { useActionState, useDeferredValue, useOptimistic, useState, useTransition } from 'react';

function SearchPage({ search }) {
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);
  const [isPending, startTransition] = useTransition();
  const [results, setResults] = useState([]);

  function handleChange(event) {
    const next = event.target.value;
    setQuery(next);
    startTransition(async () => {
      setResults(await search(next));
    });
  }

  return (
    <section>
      <input value={query} onChange={handleChange} />
      {isPending && <span>Loading...</span>}
      <ResultList query={deferredQuery} items={results} />
    </section>
  );
}

// React 19: Action state 统一 pending/error/result
async function updateName(previousState, formData) {
  const name = formData.get('name');
  if (!name) return { error: 'Name is required' };
  await saveName(name);
  return { error: null, savedName: name };
}

function ProfileForm() {
  const [state, formAction, isPending] = useActionState(updateName, {
    error: null,
    savedName: ''
  });

  return (
    <form action={formAction}>
      <input name="name" />
      <button disabled={isPending}>Save</button>
      {state.error && <p>{state.error}</p>}
    </form>
  );
}

// React 19: optimistic UI
function CommentList({ comments, submitComment }) {
  const [optimisticComments, addOptimisticComment] = useOptimistic(
    comments,
    (current, text) => [...current, { id: 'temp', text, pending: true }]
  );

  async function action(formData) {
    const text = formData.get('comment');
    addOptimisticComment(text);
    await submitComment(text);
  }

  return <form action={action}>{/* render optimisticComments */}</form>;
}
